//! Recorded conformance for the Rust port, under obligation PORT-6.
//!
//! The recordings were generated by running the landed Python over
//! inputs drawn from its own suite, and the answers it gave stand
//! beside the inputs in the recordings file. These tests run the Rust
//! readings against those recordings offline, comparing rendered
//! texts byte for byte and refusals by their kind and their wording.

use tameshi::ingest;
use tameshi::jsonvalue::{parse, JsonValue};
use tameshi::packs;
use tameshi::reader;
use tameshi::render::render_json;
use tameshi::rulings;
use tameshi::TameshiError;

fn recordings() -> Vec<JsonValue> {
    let path = concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/tests/conformance/port1_cases.json"
    );
    let text = std::fs::read_to_string(path).expect("the recordings file stands in the tree");
    let document = parse(&text).expect("the recordings file parses");
    document
        .get("cases")
        .and_then(|cases| cases.as_list())
        .expect("the recordings carry a case list")
        .to_vec()
}

fn cases_of_kind(kind: &str) -> Vec<JsonValue> {
    recordings()
        .into_iter()
        .filter(|case| case.get("kind").and_then(|value| value.as_text()) == Some(kind))
        .collect()
}

fn case_name(case: &JsonValue) -> &str {
    case.get("name")
        .and_then(|value| value.as_text())
        .unwrap_or("")
}

fn optional_document(case: &JsonValue, field: &str) -> Option<JsonValue> {
    match case.get(field) {
        None | Some(JsonValue::Null) => None,
        Some(value) => Some(value.clone()),
    }
}

fn optional_text_value(case: &JsonValue, field: &str) -> Option<JsonValue> {
    match case.get(field) {
        None | Some(JsonValue::Null) => None,
        Some(value) => Some(value.clone()),
    }
}

fn check_error(case: &JsonValue, outcome: Result<(), TameshiError>) {
    let expected = case
        .get("expected")
        .expect("each case carries an expectation");
    match expected.get("error") {
        Some(JsonValue::List(pair)) => {
            let class = pair.first().and_then(|value| value.as_text()).unwrap_or("");
            let message = pair.get(1).and_then(|value| value.as_text()).unwrap_or("");
            match outcome {
                Ok(()) => panic!(
                    "case {} expected the refusal {class} but the reading accepted",
                    case_name(case)
                ),
                Err(error) => {
                    assert_eq!(
                        error.class_name(),
                        class,
                        "case {} names a different refusal kind",
                        case_name(case)
                    );
                    assert_eq!(
                        error.message,
                        message,
                        "case {} names a different refusal wording",
                        case_name(case)
                    );
                }
            }
        }
        _ => {
            if let Err(error) = outcome {
                panic!(
                    "case {} expected success but the reading refused with {}",
                    case_name(case),
                    error.message
                );
            }
        }
    }
}

fn expected_text(case: &JsonValue, field: &str) -> String {
    case.get("expected")
        .and_then(|expected| expected.get(field))
        .and_then(|value| value.as_text())
        .unwrap_or("")
        .to_string()
}

#[test]
fn pack_cases_match_the_python_record() {
    let cases = cases_of_kind("assemble");
    assert!(!cases.is_empty(), "the recordings carry assemble cases");
    for case in &cases {
        let cl_packs = case
            .get("catchledger_packs")
            .and_then(|value| value.as_list())
            .expect("each assemble case carries its catchledger packs")
            .to_vec();
        let canary = optional_document(case, "canary_document");
        let blindness = optional_document(case, "blindness_document");
        let outcome = packs::assemble_packs(&cl_packs, canary.as_ref(), blindness.as_ref(), None);
        match outcome {
            Ok(assembled) => {
                check_error(case, Ok(()));
                let rendered = render_json(&JsonValue::Object(assembled));
                assert_eq!(
                    rendered,
                    expected_text(case, "packs_rendered"),
                    "case {} renders a different pack set",
                    case_name(case)
                );
            }
            Err(error) => check_error(case, Err(error)),
        }
    }
}

#[test]
fn ruling_cases_match_the_python_record() {
    let cases = cases_of_kind("ruling");
    assert!(!cases.is_empty(), "the recordings carry ruling cases");
    for case in &cases {
        let pack = case
            .get("pack")
            .expect("each ruling case carries its pack")
            .clone();
        let ruling = case
            .get("ruling")
            .and_then(|value| value.as_text())
            .unwrap_or("")
            .to_string();
        let expiry = optional_text_value(case, "expiry");
        let today = optional_text_value(case, "today");
        let outcome = rulings::generate_ruling(&pack, &ruling, expiry.as_ref(), today.as_ref());
        match outcome {
            Ok((record, body)) => {
                check_error(case, Ok(()));
                assert_eq!(
                    render_json(&record),
                    expected_text(case, "record_rendered"),
                    "case {} renders a different ruling record",
                    case_name(case)
                );
                assert_eq!(
                    body,
                    expected_text(case, "body"),
                    "case {} renders a different ruling body",
                    case_name(case)
                );
            }
            Err(error) => check_error(case, Err(error)),
        }
    }
}

#[test]
fn validation_cases_match_the_python_record() {
    let cases = cases_of_kind("validate");
    assert!(!cases.is_empty(), "the recordings carry validation cases");
    for case in &cases {
        let pack = case
            .get("pack")
            .expect("each validation case carries its pack")
            .clone();
        let cl_packs = case
            .get("catchledger_packs")
            .and_then(|value| value.as_list())
            .expect("each validation case carries its catchledger packs")
            .to_vec();
        let canary = optional_document(case, "canary_document");
        let blindness = optional_document(case, "blindness_document");
        let outcome =
            packs::validate_pack(&pack, &cl_packs, canary.as_ref(), blindness.as_ref(), None)
                .map(|_| ());
        check_error(case, outcome);
    }
}

#[test]
fn timestamp_cases_match_the_python_record() {
    let cases = cases_of_kind("timestamp");
    assert!(!cases.is_empty(), "the recordings carry timestamp cases");
    for case in &cases {
        let text = case
            .get("text")
            .and_then(|value| value.as_text())
            .unwrap_or("")
            .to_string();
        let label = case
            .get("label")
            .and_then(|value| value.as_text())
            .unwrap_or("")
            .to_string();
        let outcome = ingest::parse_timestamp(&JsonValue::Text(text), &label);
        let expected = case
            .get("expected")
            .expect("each case carries an expectation");
        match expected.get("micros") {
            Some(JsonValue::Int(want)) => match outcome {
                Ok(micros) => assert_eq!(
                    micros,
                    i128::from(*want),
                    "case {} reads a different instant",
                    case_name(case)
                ),
                Err(error) => panic!(
                    "case {} expected the instant {want} but the reading refused with {}",
                    case_name(case),
                    error.message
                ),
            },
            _ => check_error(case, outcome.map(|_| ())),
        }
    }
}

#[test]
fn a_document_nested_past_the_bound_is_refused() {
    // The reading under test recurses once per nesting level on the
    // way to the bound, so it runs on a thread carrying a stack sized
    // for the descent, the way the tool's own main thread carries it.
    let text = format!("{}{}", "[".repeat(4001), "]".repeat(4001));
    let outcome = std::thread::Builder::new()
        .stack_size(64 * 1024 * 1024)
        .spawn(move || reader::read_json_document(&text, "evidence pack"))
        .expect("the reader thread stands")
        .join()
        .expect("the reader thread finishes");
    match outcome {
        Ok(_) => panic!("a document nested past the bound was read"),
        Err(error) => {
            assert_eq!(error.class_name(), "TameshiError");
            assert_eq!(error.message, "the evidence pack is not valid JSON");
        }
    }
}

#[test]
fn a_document_nested_within_the_bound_reads() {
    let text = format!("{}1{}", "[".repeat(100), "]".repeat(100));
    let outcome = reader::read_json_document(&text, "evidence pack");
    assert!(
        outcome.is_ok(),
        "a document nested within the bound refused"
    );
}

#[test]
fn reader_cases_match_the_python_record() {
    let cases = cases_of_kind("reader");
    assert!(!cases.is_empty(), "the recordings carry reader cases");
    for case in &cases {
        let text = case
            .get("text")
            .and_then(|value| value.as_text())
            .unwrap_or("")
            .to_string();
        let label = case
            .get("label")
            .and_then(|value| value.as_text())
            .unwrap_or("")
            .to_string();
        let outcome = reader::read_json_document(&text, &label).map(|value| {
            assert_eq!(
                render_json(&value),
                expected_text(case, "rendered"),
                "case {} renders a different document",
                case_name(case)
            );
        });
        check_error(case, outcome);
    }
}

fn port2_recordings() -> Vec<JsonValue> {
    let path = concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/tests/conformance/port2_cases.json"
    );
    let text =
        std::fs::read_to_string(path).expect("the slice 2 recordings file stands in the tree");
    let document = parse(&text).expect("the slice 2 recordings file parses");
    document
        .get("cases")
        .and_then(|cases| cases.as_list())
        .expect("the slice 2 recordings carry a case list")
        .to_vec()
}

fn port2_cases_of_kind(kind: &str) -> Vec<JsonValue> {
    port2_recordings()
        .into_iter()
        .filter(|case| case.get("kind").and_then(|value| value.as_text()) == Some(kind))
        .collect()
}

#[test]
fn ingest_cases_match_the_python_record() {
    let cases = port2_cases_of_kind("ingest");
    assert_eq!(
        cases.len(),
        84,
        "the slice 2 recordings carry 84 ingest cases"
    );
    for case in &cases {
        let document = case
            .get("document")
            .expect("each ingest case carries its document")
            .clone();
        let outcome = ingest::read_catchledger_packs(&document);
        match outcome {
            Ok(packs) => {
                check_error(case, Ok(()));
                let rendered = render_json(&JsonValue::List(packs));
                assert_eq!(
                    rendered,
                    expected_text(case, "packs_rendered"),
                    "case {} renders a different pack list",
                    case_name(case)
                );
            }
            Err(error) => check_error(case, Err(error)),
        }
    }
}

#[test]
fn ingest_text_cases_match_the_python_record() {
    let cases = port2_cases_of_kind("ingest_text");
    assert_eq!(
        cases.len(),
        16,
        "the slice 2 recordings carry 16 ingest text cases"
    );
    for case in &cases {
        let text = case
            .get("text")
            .and_then(|value| value.as_text())
            .unwrap_or("")
            .to_string();
        let outcome = reader::read_json_document(&text, "catchledger evidence")
            .and_then(|document| ingest::read_catchledger_packs(&document));
        match outcome {
            Ok(packs) => {
                check_error(case, Ok(()));
                let rendered = render_json(&JsonValue::List(packs));
                assert_eq!(
                    rendered,
                    expected_text(case, "packs_rendered"),
                    "case {} renders a different pack list",
                    case_name(case)
                );
            }
            Err(error) => check_error(case, Err(error)),
        }
    }
}

#[test]
fn a_catchledger_document_nested_past_the_bound_is_refused() {
    // The nesting bound of PORT-3 as amended by RFIX-7 stands over
    // the slice 2 reading unchanged, and the recordings cannot reach
    // this case because the Python command line dies on such a
    // document, so it stands as a named pin in the shape RFIX-7 sets.
    // The reading under test recurses once per nesting level on the
    // way to the bound, so it runs on a thread carrying a stack sized
    // for the descent.
    let text = format!("{}{}", "[".repeat(4001), "]".repeat(4001));
    let outcome = std::thread::Builder::new()
        .stack_size(64 * 1024 * 1024)
        .spawn(move || {
            reader::read_json_document(&text, "catchledger evidence")
                .and_then(|document| ingest::read_catchledger_packs(&document))
        })
        .expect("the reader thread stands")
        .join()
        .expect("the reader thread finishes");
    match outcome {
        Ok(_) => panic!("a document nested past the bound was read"),
        Err(error) => {
            assert_eq!(error.class_name(), "TameshiError");
            assert_eq!(error.message, "the catchledger evidence is not valid JSON");
        }
    }
}
